import re


class Protocol_Msg_Handle(object):
    def __init__(self):
        pass

    def parse_key_value(self, line):
        'key value'
        spcical_char = [',', ':', ]
        for i in range(len(line)):
            if line[i] in spcical_char:
                bp = i
                break
        key = line[:i]
        value = line[i + 1:]
        value = value.strip()
        if '=' in key:
            key = key.split('=')[-1].strip()
        key = '_'.join([k.lower() for k in key.split()])

        if len(value) == 1 and value in ['{', '(']:
            value = None
        elif '(' and ')' in value and value.endswith(')'):
            value = value.split('(')[-1].strip(')')
        elif '[' and '[' in value and value.endswith(']'):
            value = value.split('[')[-1].strip(']')
        elif '<' and '>' in value and value.endswith('>'):
            value = value.split('<')[-1].strip('>')
        key = key.strip('[')
        value = value.strip(']')
        return key, value

    def msg_2_dict(self, data):
        'dict'
        if isinstance(data, list):
            lines = data
        else:
            lines = data.splitlines()
        lines = [x.rstrip() for x in lines]
        lines = [x for x in lines if x != '']
        index_dict = {}

        for i in range(len(lines)):
            index_dict[i] = {}
            index_dict[i]['content'] = lines[i]
            index_dict[i]['line_num'] = i
            line = lines[i].strip()
            index_dict[i]['indent'] = len(lines[i]) - len(lines[i].strip())
            for j in range(i, -1, -1):
                sub = index_dict[i]['indent'] - index_dict[j]['indent']
                if sub == 4 or sub == 8:
                    index_dict[i]['parent'] = index_dict[j]['key']
                    break

            if ':' in line or ',' in line:
                key, value = self.parse_key_value(line)
                index_dict[i]['key'] = key

                index_dict[i]['value'] = value
            elif line.endswith('{'):
                index_dict[i]['key'] = line.strip('{').strip()
                index_dict[i]['value'] = None

            elif ' ' not in line:
                index_dict[i]['key'] = line
                index_dict[i]['value'] = None
            elif ' ' in line:
                index_dict[i]['key'] = line.split()[0]
                index_dict[i]['value'] = line.split()[1]

            if 'parent' in index_dict[i].keys(
            ) and index_dict[i]['parent'] is not None:
                index_dict[i]['key'] = '%s.%s' % (
                    index_dict[i]['parent'], index_dict[i]['key'])

        check_msg = []

        for i in index_dict:
            check_msg.append('%s = %s' % (index_dict[i]
                                          ['key'], index_dict[i]['value']))
        check_msg.append(self.msg_time)
        check_msg.append(self.msg_time_ms)
        return check_msg

    def _time_to_s(self, timestampe):
        ret = re.search(r'\d\d:\d\d:\d\d([.:])\d\d\d', timestampe)
        if ret:
            spt = ret.groups()[0]
            if spt != ':':
                hms, ms = timestampe.split(spt)
                h, m, s = hms.split(':')
            else:
                h, m, s, ms = timestampe.split(spt)

            time_s = int(h) * 3600 + int(m) * 60 + int(s)
            return time_s
        else:
            return timestampe

    def parse_single_msg(self, src, type='TM500'):
        'null'
        start_pos = '^{.*'
        stop_pos = '^}.*'
        if isinstance(src, list):
            src_list = src
        else:
            src_list = src.splitlines()
        for i in range(len(src_list)):
            if re.search(start_pos, src_list[i]) or (
                    not src_list[i].startswith(' ') and src_list[i].endswith(' : {')):
                start = i

            if re.search(stop_pos, src_list[i]):
                stop = i
        if type == 'TM500':
            msg = src_list[stop].strip('}')
            timestamp = src_list[start - 1].split(' ')[0]
        else:
            msg = src_list[start - 1].split()[1]
            timestamp = src_list[start - 2].split(' ')[1]

        self.msg_time = '%s.timestamp = %s' % (msg, timestamp)
        self.msg_time_ms = '%s.timestamp_s = %s' % (msg, self._time_to_s(timestamp))
        useful_msg = src_list[start:stop + 1]
        useful_msg = [x.strip() for x in useful_msg]
        useful_msg = ''.join(useful_msg)

        pos = [m.start() for m in re.finditer('{', useful_msg)]
        pos += [m.start() for m in re.finditer('}', useful_msg)]
        pos.sort()
        useful_list = [msg]
        for i in range(len(pos) - 1):
            left = useful_msg[:pos[i + 1]].count('{')
            right = useful_msg[:pos[i + 1]].count('}')
            space_num = (left - right) * 4
            uu = useful_msg[pos[i] + 1:pos[i + 1]
                            ].strip().strip(':').strip(',').strip()

            if useful_msg[pos[i]
                          ] == '{' and useful_msg[pos[i + 1]] == '}' and 'range' in uu:
                useful_list[-1] = useful_list[-1] + ':' + uu
            elif useful_msg[pos[i]] == '{' and useful_msg[pos[i + 1]] == '}' and \
                    (useful_list[-1].endswith('mcc') or useful_list[-1].endswith('mnc')):
                useful_list[-1] = useful_list[-1] + ':' + uu.replace(',', '')

            else:
                if ',' in uu:
                    for u in uu.split(','):
                        useful_list.append(" " * space_num + u)
                elif uu:
                    useful_list.append(" " * space_num + uu)

        return self.msg_2_dict(useful_list)

    def parse_file(self, file_path):
        'null'
        with open(file_path, 'r') as obj:
            lines = obj.read()
        msg_dict = {}
        if 'TM500 LTE' in lines:
            type = 'TM500'
        else:
            type = 'RRC'
        line_num = []
        lines = lines.splitlines()
        # start = 0
        for i in range(len(lines)):
            if lines[i].startswith('}'):
                line_num.append(i)
        for i in range(len(line_num)):
            if i == 0:
                ret = self.parse_single_msg(lines[:line_num[i] + 1], type)
            else:
                ret = self.parse_single_msg(
                    lines[line_num[i - 1] + 1:(line_num[i]) + 1], type)
            msg_dict[i] = ret
        self.search_list = sorted(msg_dict)

        with open('%s_decode' % file_path, 'w') as obj:
            for i in sorted(msg_dict):

                obj.writelines('\r\n'.join(msg_dict[i]) + '\r\n\r\n')
        return msg_dict
